<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, reactive, ref } from 'vue'
import { Modal, message } from 'ant-design-vue'
import { Plus, RefreshCw } from 'lucide-vue-next'
import { useI18n } from 'vue-i18n'
import client from '@/api/client'
import { apiErrorMessage, type ResourceRecord } from '@/api/resources'
import { useAuthStore } from '@/stores/auth'
import PageToolbar from '@/components/PageToolbar.vue'
import ResourceTable from '@/components/ResourceTable.vue'
import ResourceDetailDrawer from '@/components/ResourceDetailDrawer.vue'
import PermissionPreview from '@/components/PermissionPreview.vue'
interface Project extends ResourceRecord {id:string;name:string;description:string;department_id:string;department_name?:string;is_active:boolean;is_default:boolean;updated_at:string}
interface Role {id:string;display_name:string;permissions:string[]}
interface Member extends ResourceRecord {user_id:string;username:string;nickname:string;role_id:string;role_name:string}
interface Detail {project:Project;members:Member[];users:Array<{id:string;username:string;nickname:string}>;roles:Role[];permissions:string[];catalog:Array<{code:string;resource:string;resource_name:string;action:string;action_name:string;description:string}>}
const {t}=useI18n(),auth=useAuthStore()
const rows=ref<Project[]>([]),departments=ref<Array<{id:string;name:string}>>([]),query=ref(''),loading=ref(false),saving=ref(false),open=ref(false),formOpen=ref(false),editingID=ref(''),selected=ref<Detail|null>(null)
const form=reactive({name:'',description:'',department_id:'',is_active:true}),member=reactive({user_id:'',role_id:''}),roleDrafts=reactive<Record<string,string>>({})
const filtered=computed(()=>rows.value.filter(item=>`${item.name} ${item.description}`.toLowerCase().includes(query.value.toLowerCase())))
const columns=computed(()=>[{key:'name',label:t('workspace.name')},{key:'department_id',label:t('workspace.department'),width:'180px'},{key:'is_active',label:t('workspace.status'),width:'110px'},{key:'updated_at',label:t('workspace.updated'),width:'190px'}])
const can=(code:string)=>auth.user?.is_superuser||selected.value?.permissions.includes(code)||selected.value?.permissions.includes('*')
const roleOptions=computed(()=>selected.value?.roles.map(role=>({value:role.id,label:role.display_name,disabled:!auth.user?.is_superuser&&!role.permissions.every(code=>selected.value?.permissions.includes(code))}))||[])
const preview=computed(()=>selected.value?.roles.find(role=>role.id===member.role_id)?.permissions||[])
async function load(){loading.value=true;try{rows.value=(await client.get<{projects:Project[]}>('/projects')).data.projects;if(auth.canAny(['department.read']))departments.value=(await client.get<{departments:typeof departments.value}>('/departments')).data.departments}catch(error){message.error(apiErrorMessage(error))}finally{loading.value=false}}
let revision=0
async function detail(id:string){const request=++revision;try{const value=(await client.get<Detail>(`/projects/${encodeURIComponent(id)}`)).data;if(request!==revision)return;selected.value=value;Object.assign(roleDrafts,Object.fromEntries(value.members.map(item=>[item.user_id,item.role_id])));Object.assign(member,{user_id:'',role_id:''});open.value=true}catch(error){if(request===revision)message.error(apiErrorMessage(error))}}
function closeDetail(){revision++;open.value=false;selected.value=null}
function edit(item?:Project){editingID.value=item?.id||'';Object.assign(form,{name:item?.name||'',description:item?.description||'',department_id:item?.department_id||auth.user?.department_id||'',is_active:item?.is_active??true});formOpen.value=true}
async function save(){if(!form.name.trim()||saving.value)return;saving.value=true;try{if(editingID.value)await client.put(`/projects/${editingID.value}`,form);else await client.post('/projects',form);formOpen.value=false;message.success(t('workspace.saved'));window.dispatchEvent(new Event('edo:projects-changed'));await load();if(open.value&&selected.value)await detail(selected.value.project.id)}catch(error){message.error(apiErrorMessage(error))}finally{saving.value=false}}
function assign(userID:string,roleID:string){if(!selected.value||saving.value)return;const id=selected.value.project.id;Modal.confirm({title:t('workspace.confirmMember'),async onOk(){saving.value=true;try{await client.put(`/projects/${id}/members/${userID}`,{role_id:roleID});message.success(t('workspace.saved'));await detail(id)}catch(error){message.error(apiErrorMessage(error));throw error}finally{saving.value=false}}})}
function remove(item:Project){Modal.confirm({title:t('workspace.confirmDelete'),content:t('workspace.confirmDeleteHint'),okType:'danger',async onOk(){try{await client.delete(`/projects/${item.id}`);open.value=false;window.dispatchEvent(new Event('edo:projects-changed'));await load()}catch(error){message.error(apiErrorMessage(error));throw error}}})}
function useProject(item:Project){localStorage.setItem('edo.project',item.id);window.location.assign('/applications')}
onBeforeUnmount(()=>{revision++})
onMounted(load)
</script>
<template><section><PageToolbar :description="t('workspace.description')"><a-button @click="load" :aria-label="t('workspace.refresh')" :loading="loading"><RefreshCw :size="15"/></a-button><a-button v-if="auth.canAny(['project.create'])" type="primary" @click="edit()"><Plus :size="15"/>{{t('workspace.create')}}</a-button></PageToolbar><div class="workspace-search"><a-input-search v-model:value="query" allow-clear :placeholder="t('workspace.search')"/></div><div class="vben-card"><ResourceTable :rows="filtered" :columns="columns" :loading="loading" :details="false"><template #cell-name="{row}"><button class="project-name" @click="detail(String(row.id))">{{row.name}}</button><a-tag v-if="row.is_default&&row.name!==t('workspace.default')" class="default-tag">{{t('workspace.default')}}</a-tag><p class="muted">{{row.description||'—'}}</p></template><template #cell-department_id="{row}">{{row.department_name||departments.find(item=>item.id===row.department_id)?.name||auth.user?.department_name||'—'}}</template><template #cell-is_active="{row}"><a-tag :color="row.is_active?'success':'default'">{{row.is_active?t('workspace.enabled'):t('workspace.disabled')}}</a-tag></template><template #cell-updated_at="{row}"><time>{{new Date(String(row.updated_at)).toLocaleString()}}</time></template><template #actions="{row}"><a-button size="small" @click="detail(String(row.id))">{{t('workspace.details')}}</a-button><a-button v-if="row.is_active" size="small" @click="useProject(row as Project)">{{t('workspace.useProject')}}</a-button></template></ResourceTable></div>
<ResourceDetailDrawer v-model:open="open" :title="selected?.project.name" @close="closeDetail"><template #actions><a-button v-if="selected&&can('project.update')" @click="edit(selected.project)">{{t('workspace.edit')}}</a-button><a-button v-if="selected&&!selected.project.is_default&&can('project.delete')" danger @click="remove(selected.project)">{{t('workspace.remove')}}</a-button></template><template v-if="selected"><a-alert :message="selected.project.is_default?t('workspace.defaultHint'):t('workspace.note')" type="info" show-icon/><section class="resource-detail-section"><h4>{{t('workspace.members')}}</h4><template v-if="can('project.member.update')"><p class="muted">{{t('workspace.scopedHint')}}</p><div class="member-add"><a-select  :value="member.user_id||undefined" @update:value="member.user_id=String($event||'')" :aria-label="t('workspace.user')" show-search option-filter-prop="label" :placeholder="t('workspace.user')" :options="selected.users.map(item=>({value:item.id,label:item.nickname||item.username}))"/><a-select :value="member.role_id||undefined" @update:value="member.role_id=String($event||'')" :aria-label="t('workspace.role')" show-search option-filter-prop="label" :placeholder="t('workspace.role')" :options="roleOptions"/><a-button type="primary" :disabled="!member.user_id||!member.role_id||saving" @click="assign(member.user_id,member.role_id)">{{t('workspace.addMember')}}</a-button></div><PermissionPreview v-if="member.role_id" :codes="preview" :catalog="selected.catalog"/><div class="project-members"><ResourceTable :rows="selected.members" row-key="user_id" :columns="[{key:'nickname',label:t('workspace.user')},{key:'role_name',label:t('workspace.role')}]" :details="false"><template #cell-role_name="{row}"><a-select v-model:value="roleDrafts[String(row.user_id)]" :options="roleOptions" style="width:190px" :disabled="!auth.user?.is_superuser&&row.user_id===auth.user?.id"/></template><template #actions="{row}"><a-button size="small" :disabled="saving||roleDrafts[String(row.user_id)]===row.role_id" @click="assign(String(row.user_id),roleDrafts[String(row.user_id)]||'')">{{t('workspace.save')}}</a-button><a-button size="small" danger :disabled="saving||(!auth.user?.is_superuser&&row.user_id===auth.user?.id)" @click="assign(String(row.user_id),'')">{{t('workspace.removeMember')}}</a-button></template></ResourceTable></div></template><a-alert v-else :message="t('workspace.noMemberAccess')" type="info"/></section><section class="resource-detail-section"><h4>{{t('workspace.effective')}}</h4><PermissionPreview :codes="selected.permissions" :catalog="selected.catalog"/></section></template></ResourceDetailDrawer>
<a-drawer v-model:open="formOpen" :title="editingID?t('workspace.edit'):t('workspace.create')" width="min(620px, 94vw)" :closable="!saving" :mask-closable="!saving"><a-form layout="vertical" @finish="save"><a-form-item :label="t('workspace.name')" required><a-input v-model:value="form.name" :maxlength="96"/></a-form-item><a-form-item :label="t('workspace.department')"><a-select v-if="auth.user?.is_superuser&&!editingID" v-model:value="form.department_id" :options="departments.map(item=>({value:item.id,label:item.name}))"/><a-input v-else :value="departments.find(item=>item.id===form.department_id)?.name||rows.find(item=>item.department_id===form.department_id)?.department_name||auth.user?.department_name" disabled/></a-form-item><a-form-item :label="t('workspace.descriptionField')"><a-textarea v-model:value="form.description" :maxlength="255" :rows="3"/></a-form-item><a-form-item v-if="editingID" :label="t('workspace.status')"><a-switch v-model:checked="form.is_active" :disabled="selected?.project.is_default"/></a-form-item></a-form><template #footer><div class="drawer-actions"><a-button :disabled="saving" @click="formOpen=false">{{t('workspace.cancel')}}</a-button><a-button type="primary" :loading="saving" @click="save">{{t('workspace.save')}}</a-button></div></template></a-drawer></section></template>
<style scoped>.workspace-search{max-width:340px;margin-bottom:14px}.project-name{border:0;background:none;color:var(--edo-primary);font-weight:600;padding:0;cursor:pointer;font-size:14px}.muted{font-size:12px;color:var(--edo-muted);margin:6px 0;max-width:560px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.default-tag{margin-inline-start:10px}.member-add{display:flex;gap:10px;margin:14px 0;flex-wrap:wrap}.member-add .ant-select{min-width:200px;flex:1}.drawer-actions{display:flex;justify-content:flex-end;gap:8px}.project-members :deep(.resource-table){min-width:620px}</style>
